import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, nowIso, rowToJob, transaction, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1024 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const HEARTBEAT_FRESH_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

const db: DatabaseSync = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers?: Record<string, string>,
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields !== undefined) error.fields = fields;
  send(res, status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true; // keep draining so the response can be written cleanly
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

type Validated = { input: string; steps: number; failAttempts: number };

function validateIntegerField(obj: Record<string, unknown>, name: string, def: number, min: number, max: number, fields: FieldError[]): number {
  const v = obj[name];
  if (v === undefined) return def;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return def;
  }
  return v;
}

/** Validates a POST /api/jobs request. Collects every problem before reporting. */
function validateCreate(req: IncomingMessage, text: string, tooLarge: boolean, fields: FieldError[]): Validated | null {
  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return null;
  }
  if (tooLarge) {
    fields.push({ field: 'body', message: 'body is too large' });
    return null;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    fields.push({ field: 'body', message: 'malformed JSON' });
    return null;
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return null;
  }
  const obj = parsed as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: `unknown field ${key}` });
  }
  const input = obj.input;
  if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'input must be a non-blank string of 1 to 1000 characters' });
  }
  const steps = validateIntegerField(obj, 'steps', 5, 1, 20, fields);
  const failAttempts = validateIntegerField(obj, 'failAttempts', 0, 0, 5, fields);
  if (typeof input !== 'string' || fields.length > 0) return null;
  return { input, steps, failAttempts };
}

type CreateOutcome = { status: 200 | 201; row: JobRow } | { conflict: true };

function findByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

function compareWithExisting(existing: JobRow, payload: string): CreateOutcome {
  return existing.payload === payload ? { status: 200, row: existing } : { conflict: true };
}

function createJob(v: Validated, key: string | null): CreateOutcome {
  const payload = JSON.stringify({ input: v.input, steps: v.steps, failAttempts: v.failAttempts });
  const attempt = (): CreateOutcome =>
    transaction(db, () => {
      if (key !== null) {
        const existing = findByKey(key);
        if (existing) return compareWithExisting(existing, payload);
      }
      const now = nowIso();
      const id = randomUUID();
      db.prepare(
        `INSERT INTO jobs(id, status, input, steps, fail_attempts, attempts, progress_completed,
           idempotency_key, payload, run_after, created_at, updated_at)
         VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
      ).run(id, v.input, v.steps, v.failAttempts, key, payload, now, now);
      const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
      return { status: 201, row };
    });
  try {
    return attempt();
  } catch (err) {
    // A concurrent insert with the same key won the race. Compare against the winner.
    if (key !== null && err instanceof Error && err.message.includes('UNIQUE constraint failed')) {
      const existing = findByKey(key);
      if (existing) return compareWithExisting(existing, payload);
    }
    throw err;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const value = String(rawKey);
    if (IDEMPOTENCY_KEY_RE.test(value)) key = value;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const validated = validateCreate(req, text, tooLarge, fields);
  if (fields.length > 0 || validated === null) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
  }

  const outcome = createJob(validated, key);
  if ('conflict' in outcome) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.status, rowToJob(outcome.row));
}

function handleHealth(res: ServerResponse): void {
  const row = db.prepare('SELECT ts FROM heartbeat WHERE id = 1').get() as { ts: number | bigint } | undefined;
  const alive = row !== undefined && Date.now() - Number(row.ts) < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: alive ? 'up' : 'down' });
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGet(res: ServerResponse, id: string): void {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
  send(res, 200, rowToJob(row));
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return void res.end(uiHtml);
  }
  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'Job not found.');
    }
    return handleGet(res, id);
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  const fallback = setTimeout(() => process.exit(0), 2000);
  fallback.unref();
  server.close(() => {
    try {
      db.close();
    } catch {
      // already closed
    }
    process.exit(0);
  });
  server.closeAllConnections();
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

