import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_MS = 200;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

function writeHeartbeat(ts: number): void {
  db.prepare('INSERT INTO heartbeat(id, ts) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET ts = excluded.ts').run(ts);
}

function beat(): void {
  try {
    writeHeartbeat(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/** Returns an interrupted job to the queue. The interrupted attempt is not counted, so it re-runs with the same number. */
function requeueInterrupted(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(nowIso(), id);
}

/** Claims the oldest runnable queued job, atomically. Returns undefined when there is none. */
function claim(): JobRow | undefined {
  return transaction(db, () => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1")
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(nowIso(), row.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(row.id) as unknown as JobRow;
  });
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, nowIso(), id);
}

function complete(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, error = NULL, updated_at = ? WHERE id = ?",
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

/** Records a failed attempt: retry while attempts remain, otherwise mark the job failed. */
function failAttempt(job: JobRow): void {
  if (job.attempts < MAX_ATTEMPTS) {
    db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?",
    ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
  } else {
    db.prepare(
      "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, updated_at = ? WHERE id = ?",
    ).run(nowIso(), job.id);
  }
}

/** Runs one attempt. `job.attempts` is already the number of this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return requeueInterrupted(job.id);
    return failAttempt(job);
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return requeueInterrupted(job.id);
    setProgress(job.id, step);
  }
  complete(job);
}

async function loop(): Promise<void> {
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = claim();
    } catch (err) {
      console.error('claim failed:', err);
    }
    if (!job) {
      await sleep(IDLE_MS);
      continue;
    }
    try {
      await runAttempt(job);
    } catch (err) {
      console.error(`attempt for job ${job.id} failed:`, err);
      try {
        requeueInterrupted(job.id);
      } catch {
        // the next startup recovery will pick it up
      }
    }
  }
}

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  const fallback = setTimeout(() => process.exit(0), 3000);
  fallback.unref();
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, shutdown);

// Startup: heartbeat first, then recover jobs left running by a previous worker that died.
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);
db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
).run(nowIso());

console.log('worker started');
await loop();

clearInterval(heartbeatTimer);
try {
  writeHeartbeat(0);
} catch {
  // best effort: a stale heartbeat also reads as down
}
db.close();
process.exit(0);

